    detail, detailN, mask,
    setWet(v) { ent.uniforms({ uWetG: v }) },
    setRain(v) { ent.uniforms({ uRain: v }) },
    destroy() { for (const o of [ent, mask, detail, detailN] as { destroy(): void }[]) { try { o.destroy() } catch { /* 已回收 */ } } },
  }
}

