files.harbor/shaders/rain.vert:
// 原版雨滴（pretty.js Ub + kR）机械移植。原版是实例化网格（每实例 aSeed vec4）；gfx 没有实例化，
// 由 rain.ts 把每个实例的 4 个角点直接展开进网格：pot_Position = 角点 (x, y, 0)，pot_Normal = aSeed.xyz，pot_UV.x = aSeed.w。
// 计算在原版 three 坐标下进行（z 取反），输出时转回 Unity。绑定须 frustumCull:false（位置在这里重算，网格包围盒不可信）。
#include <pot/varyings>

uniform float uRain, uDrip;
uniform vec3 uVel, uBox, uSunDir, uSunCol, uAmb;
// 室内盒子（three 坐标，已外扩）与天窗 (x, z, 半宽, 半深)：室内不下雨，天窗下照下
uniform vec4 uBoxMin[4];
uniform vec4 uBoxMax[4];
uniform vec4 uSky[8];

bool wInside(vec3 p) {
  for (int i = 0; i < 4; i++) { if (all(greaterThan(p, uBoxMin[i].xyz)) && all(lessThan(p, uBoxMax[i].xyz))) return true; }
  return false;
}
bool wSky(vec3 p) {
  for (int i = 0; i < 8; i++) { if (abs(p.x - uSky[i].x) < uSky[i].z && abs(p.z - uSky[i].y) < uSky[i].w) return true; }
  return false;
}
float wPhase(float c) { float g = 0.72; return (1.0 - g * g) / (12.566 * pow(1.0 + g * g - 2.0 * g * c, 1.5)); }

void main() {
  float uTime = pot_Time.x;
  vec4 aSeed = vec4(pot_Normal, pot_UV.x);
  vec3 cameraPosition = vec3(pot_CameraPos.x, pot_CameraPos.y, -pot_CameraPos.z);
  // 原版 uPix = 2·tan(fov/2) / 屏幕高（像素在 1 米处对应的世界尺寸）
  float uPix = 2.0 * pot_Camera.z * pot_Resolution.w;
  vec2 uv = pot_Position.xy;
  float sp = 0.82 + 0.36 * aSeed.w;
  vec3 vel = uVel * sp;
  vec3 p; float len; float kill = 0.0;
  if (aSeed.w < 0.0) {                       // 仓库南檐滴水线，从 7 m 自由落下
    float T = 1.19; float t = fract(uTime / T * (0.9 + 0.2 * aSeed.y) + aSeed.z) * T;
    p = vec3(mix(-16.0, 12.0, aSeed.x), 7.0 - 4.9 * t * t, -10.72 + 0.05 * sin(aSeed.x * 911.0));
    vel = vec3(0.0, -9.81 * t - 0.3, 0.0); len = 0.022 * length(vel) + 0.03;
    kill = 1.0 - uDrip;
    if (fract(aSeed.x * 37.7) > 0.55 + 0.45 * uRain) kill = 1.0;
  } else {
    p = aSeed.xyz * uBox + vel * uTime;
    p = mod(p - cameraPosition + 0.5 * uBox, uBox) - 0.5 * uBox + cameraPosition;
    len = 0.03 * length(vel);
    if (fract(aSeed.w * 7.13 + aSeed.x) > uRain) kill = 1.0;
    if (wInside(p) && !wSky(p)) kill = 1.0;
  }
  if (p.y < (p.x > 30.0 ? -1.6 : 0.0)) kill = 1.0;
  vec3 dir = normalize(vel);
  vec3 toP = p - cameraPosition; float dist = length(toP);
  vec3 side = normalize(cross(dir, toP));
  float w0 = 0.005 + 0.004 * fract(aSeed.w * 3.7);
  float w = max(w0, dist * uPix * 0.75);
  vec3 wp = p + dir * (len * (uv.y - 0.5)) + side * (w * uv.x);
  float a = (w0 / w) * smoothstep(0.7, 2.6, dist) * (1.0 - smoothstep(0.38, 0.5, dist / uBox.x));
  float c = dot(toP / max(dist, 1e-3), uSunDir);
  vec3 world = vec3(wp.x, wp.y, -wp.z);
  vWorldPos = world;
  vNormal = vec3(0.0, 1.0, 0.0);
  vUV = uv;
  vColor = vec4(uAmb + uSunCol * wPhase(c), a * (0.55 + 0.45 * fract(aSeed.w * 13.3)));
  vTangent = vec4(1.0, 0.0, 0.0, 1.0);
  gl_Position = kill > 0.5 ? vec4(2.0, 2.0, 2.0, 1.0) : pot_ViewProj * vec4(world, 1.0);
}

files.harbor/shaders/sea.frag:
// 原版海面 kb 片元部分（pretty.js zR/DR/LR + 太阳闪光）机械移植；光照走 <pot/lit>。
// 坐标：vGWorld 为原版 three 世界坐标（位移前），法线 three (-gNxz.x, 1, -gNxz.y) → Unity (-gNxz.x, 1, gNxz.y)。
// 与原版的差异：
// - 原版 gOcc 乘在直射 radiance 与漫反射 IBL 上（不影响镜面 IBL）；这里折算为 albedo 与 s.specular 乘 gOcc，s.ao 保持 1
// - 原版 directSpecular 先对所有光源求和再钳到 40；这里按光源逐个钳（s.specularMax）
#include <pot/varyings>
#include <pot/lit>

uniform sampler2D uDetail, uDetailN;
uniform vec3 uHazeA, uHazeB;

in vec3 vGWorld;
in float vSAmp;

out vec4 fragColor;

void main() {
  vec3 cameraPosition = vec3(pot_CameraPos.x, pot_CameraPos.y, -pot_CameraPos.z);
  vec3 uSunDirW = vec3(pot_SunDir.x, pot_SunDir.y, -pot_SunDir.z);
  float uTime = pot_Time.x;
  vec3 diffuseColor = vec3(1.0);
  float gRough; vec2 gNxz; float gOcc; float gSDist; float gSpark;
  // ===== DR =====
  {
    vec2 sxz = vGWorld.xz;
    float sd = length(cameraPosition - vGWorld); gSDist = sd;
    vec2 slopeA = vec2(0.0), slopeB = vec2(0.0);
    slopeA += vec2(-0.92069, 0.39029) * (0.03968 * cos(0.66139 * dot(vec2(-0.92069, 0.39029), sxz) - 2.54720 * uTime));
    slopeA += vec2(-0.75071, -0.66063) * (0.04409 * cos(1.10231 * dot(vec2(-0.75071, -0.66063), sxz) - 3.28842 * uTime));
    slopeA += vec2(-0.99273, 0.12033) * (0.04950 * cos(1.90400 * dot(vec2(-0.99273, 0.12033), sxz) - 4.32183 * uTime));
    slopeA += vec2(-0.49828, 0.86701) * (0.05027 * cos(3.14159 * dot(vec2(-0.49828, 0.86701), sxz) - 5.55149 * uTime));
    slopeB += vec2(-0.80000, 0.60000) * (0.09593 * cos(4.79632 * dot(vec2(-0.80000, 0.60000), sxz) - 6.85944 * uTime));
    slopeB += vec2(-0.95067, -0.31022) * (0.10598 * cos(7.57010 * dot(vec2(-0.95067, -0.31022), sxz) - 8.61758 * uTime));
    slopeB += vec2(-0.34894, -0.93715) * (0.11023 * cos(11.02313 * dot(vec2(-0.34894, -0.93715), sxz) - 10.39889 * uTime));
    slopeB += vec2(-0.60000, 0.80000) * (0.11278 * cos(16.11073 * dot(vec2(-0.60000, 0.80000), sxz) - 12.57165 * uTime));
    slopeB += vec2(-0.99875, 0.04994) * (0.11636 * cos(23.27106 * dot(vec2(-0.99875, 0.04994), sxz) - 15.10924 * uTime));
    slopeB += vec2(0.30113, 0.95358) * (0.08021 * cos(13.36848 * dot(vec2(0.30113, 0.95358), sxz) - 11.45185 * uTime));
    slopeB += vec2(-0.86013, -0.51008) * (0.10472 * cos(29.91993 * dot(vec2(-0.86013, -0.51008), sxz) - 17.13227 * uTime));
    float nearB = 1.0 - smoothstep(25.0, 110.0, sd);
    vec2 t1 = texture(uDetailN, sxz * 0.113 + uTime * vec2(-0.021, 0.009)).ba - 0.5;
    vec2 t2 = texture(uDetailN, sxz * 0.031 + uTime * vec2(-0.007, -0.004)).ba - 0.5;
    vec2 t3 = texture(uDetailN, sxz.yx * 0.39 + uTime * vec2(0.031, -0.027)).ba - 0.5;
    gNxz = slopeA * vSAmp + slopeB * nearB + t1 * 0.2 + t2 * 0.24 + t3 * 0.1 * nearB;
    // 码头墙（x = 30）与系泊船体 x[33,49] z[-60,-9] 周围的泡沫、浮渣
    float dq = sxz.x - 30.0;
    vec2 hq = abs(sxz - vec2(41.0, -34.5)) - vec2(4.0, 21.5);
    float dh = length(max(hq, 0.0)) + min(max(hq.x, hq.y), 0.0) - 4.0;
    float de = min(dq, dh);
    vec4 fn = texture(uDetail, sxz * 0.41 + uTime * vec2(-0.012, 0.007));
    vec4 fn2 = texture(uDetail, sxz * 0.093 + uTime * vec2(0.004, 0.003));
    float band = 1.0 - smoothstep(0.0, 0.2 + fn2.g * fn2.g * 2.2, de);
    float foam = clamp(band * smoothstep(0.5, 0.68, fn.a * 0.55 + fn.r * 0.25 + fn2.g * 0.3 + band * 0.2), 0.0, 1.0) * step(-0.3, de);
    float scum = (1.0 - smoothstep(0.0, 5.0, de)) * smoothstep(0.4, 0.7, fn2.g);
    vec3 alb = vec3(0.0045, 0.013, 0.017);
    alb = mix(alb, vec3(0.03, 0.04, 0.034), scum * 0.6);
    alb = mix(alb, vec3(0.3, 0.32, 0.3), foam * 0.7);
    diffuseColor.rgb *= alb;
    // 风的结构：大片猫爪风区（更皱、更暗、更钝）与平静油膜相间，再加长涌浪明暗
    vec4 fn3 = texture(uDetail, sxz * 0.0123 + uTime * vec2(0.0016, 0.0011));
    float gust = smoothstep(0.38, 0.62, fn2.g * 0.45 + fn3.g * 0.75 - 0.1);
    float swell = sin(dot(sxz, vec2(-0.118, 0.05)) - uTime * 0.55 + fn3.a * 5.0) * 0.5 + 0.5;
    gNxz = gNxz * mix(0.4, 1.35, gust) + vec2(-0.92, 0.39) * (swell - 0.5) * 0.07;
    gSpark = mix(0.55, 1.0, swell) * mix(1.0, 0.6, gust);
    diffuseColor.rgb *= mix(1.0, 0.6, gust);
    gRough = mix(mix(0.1, 0.32, smoothstep(12.0, 380.0, sd)) * mix(0.62, 1.5, gust), 0.65, max(foam, scum * 0.3));
    gNxz *= 1.0 - foam * 0.6;
    gOcc = mix(0.3, 1.0, smoothstep(0.0, 8.0, de)) * mix(0.8, 1.05, swell);
  }
  // 太阳闪光：沿太阳方位最强，两侧减弱；被涌浪与风区打散
  vec3 sv = normalize(vGWorld - cameraPosition);
  float az = max(dot(normalize(sv.xz + vec2(1e-5)), normalize(uSunDirW.xz)), 0.0);
  // ===== 光照（原版 MeshStandardMaterial roughness 0.1 → pot_LitColor） =====
  PotSurface s = pot_DefaultSurface(normalize(vec3(-gNxz.x, 1.0, gNxz.y)));
  s.albedo = diffuseColor * gOcc;
  s.roughness = gRough;
  s.metallic = 0.0;
  s.specular = gOcc * gSpark * mix(0.3, 1.0, az * az * az);
  s.specularMax = 40.0;
  vec3 outgoingLight = pot_LitColor(s, vWorldPos);
  // ===== LR：远处雾霭（朝太阳偏暖，背太阳偏冷） =====
  {
    float toSun = pow(max(dot(normalize(sv.xz + vec2(1e-5)), normalize(uSunDirW.xz)), 0.0), 3.0);
    vec3 hz = mix(uHazeA, uHazeB, toSun);
    outgoingLight = mix(outgoingLight, hz, smoothstep(220.0, 860.0, gSDist) * 0.8);
  }
  fragColor = vec4(pot_ApplyFog(outgoingLight, vWorldPos), 1.0);
}

files.harbor/shaders/sea.vert:
// 原版海面 kb 顶点部分（pretty.js CR）机械移植：4 个 Gerstner 波，离码头 (30, 0) 50..220 m 内逐渐衰减到 0。
// 计算在原版 three 坐标下进行：swp = (x, y, -z)，位移的 z 分量转回 Unity 时取反。
// 常量由原版 B1 表按 fi() 格式化生成（方向已归一化，k = 2π/λ，ω = sqrt(9.81k)）。
#include <pot/varyings>

out vec3 vGWorld;
out float vSAmp;

void main() {
  float uTime = pot_Time.x;
  vec4 world = pot_Model * vec4(pot_Position, 1.0);
  vec3 swp = vec3(world.x, world.y, -world.z);
  vSAmp = 1.0 - smoothstep(50.0, 220.0, distance(swp.xz, vec2(30.0, 0.0)));
  vec3 sdisp = vec3(0.0);
  { float ph = 0.66139 * dot(vec2(-0.92069, 0.39029), swp.xz) - 2.54720 * uTime; sdisp.y += 0.06000 * sin(ph); sdisp.xz += vec2(-0.92069, 0.39029) * (0.03600 * cos(ph)); }
  { float ph = 1.10231 * dot(vec2(-0.75071, -0.66063), swp.xz) - 3.28842 * uTime; sdisp.y += 0.04000 * sin(ph); sdisp.xz += vec2(-0.75071, -0.66063) * (0.02400 * cos(ph)); }
  { float ph = 1.90400 * dot(vec2(-0.99273, 0.12033), swp.xz) - 4.32183 * uTime; sdisp.y += 0.02600 * sin(ph); sdisp.xz += vec2(-0.99273, 0.12033) * (0.01560 * cos(ph)); }
  { float ph = 3.14159 * dot(vec2(-0.49828, 0.86701), swp.xz) - 5.55149 * uTime; sdisp.y += 0.01600 * sin(ph); sdisp.xz += vec2(-0.49828, 0.86701) * (0.00960 * cos(ph)); }
  sdisp *= vSAmp;
  // 原版 vGWorld 取位移前的位置（片元的斜率、泡沫都按它计算）
  vGWorld = swp;
  world.xyz += vec3(sdisp.x, sdisp.y, -sdisp.z);
  vWorldPos = world.xyz;
  vNormal = vec3(0.0, 1.0, 0.0);
  vUV = pot_UV;
  vColor = vec4(1.0);
  vTangent = vec4(1.0, 0.0, 0.0, 1.0);
  gl_Position = pot_ViewProj * world;
}

files.harbor/shaders/splash.frag:
// 原版溅射片元（pretty.js NR）：小水冠 + 中心水柱（dots 在原版里乘 0，保留以便对照）。
#include <pot/varyings>

in float vLife;

out vec4 fragColor;

void main() {
  float x = vUV.x * 2.0, y = vUV.y;
  float dome = smoothstep(1.0, 0.25, length(vec2(x * 1.15, y * 1.5)));
  float crown = dome * (0.35 + 0.65 * smoothstep(0.25, 0.75, length(vec2(x, y * 1.4))));
  float core = smoothstep(0.5, 0.0, length(vec2(x * 1.6, (y - 0.25) * 1.6))) * (1.0 - vLife);
  float dots = smoothstep(0.16, 0.05, length(vec2(abs(x) - 0.75, y - 0.82))) + smoothstep(0.14, 0.04, length(vec2(x - 0.2, y - 0.93)));
  float a = clamp(crown * 0.5 + core * 0.8 + dots * 0.0, 0.0, 1.0) * vColor.a * 0.6;
  if (a < 0.003) discard;
  fragColor = vec4(vColor.rgb, a);
}

files.harbor/shaders/splash.vert:
// 原版雨点溅射（pretty.js UR）机械移植。实例展开方式同 rain.vert（pot_Normal = aSeed.xyz，pot_UV.x = aSeed.w）。
// 位置以相机所在 4 m 网格对齐、在 ±15 m 内随周期重抽；积水处（apron 遮罩 r < 0.49）更密更大。three 坐标计算。
#include <pot/varyings>

uniform float uRain;
uniform vec3 uSunDir, uSunCol, uAmb, uMaskRect;
uniform sampler2D uMask;
uniform vec4 uBoxMin[4];
uniform vec4 uBoxMax[4];

out float vLife;

bool wInside(vec3 p) {
  for (int i = 0; i < 4; i++) { if (all(greaterThan(p, uBoxMin[i].xyz)) && all(lessThan(p, uBoxMax[i].xyz))) return true; }
  return false;
}
float wPhase(float c) { float g = 0.72; return (1.0 - g * g) / (12.566 * pow(1.0 + g * g - 2.0 * g * c, 1.5)); }
vec2 sHash(vec2 p) { vec3 q = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973)); q += dot(q, q.yzx + 33.33); return fract((q.xx + q.yz) * q.zy); }

void main() {
  float uTime = pot_Time.x;
  vec4 aSeed = vec4(pot_Normal, pot_UV.x);
  vec3 cameraPosition = vec3(pot_CameraPos.x, pot_CameraPos.y, -pot_CameraPos.z);
  vec2 uv = pot_Position.xy;
  float period = 0.26 + 0.14 * aSeed.z;
  float tt = uTime / period + aSeed.w * 10.0; float cyc = floor(tt); float life = fract(tt);
  vec2 r = sHash(aSeed.xy * 91.7 + cyc * 0.371);
  vec2 rr = r - 0.5; rr *= 0.35 + 1.3 * abs(rr);                    // 越靠近玩家越密
  vec2 snap = floor(cameraPosition.xz / 4.0) * 4.0;
  vec3 p = vec3(snap.x + rr.x * 30.0, 0.0, snap.y + rr.y * 30.0);
  float kill = 0.0;
  vec2 muv = (p.xz - uMaskRect.xy) * uMaskRect.z;
  float inM = step(0.0, muv.x) * step(muv.x, 1.0) * step(0.0, muv.y) * step(muv.y, 1.0);
  float pud = step(textureLod(uMask, muv, 0.0).r, 0.49) * inM;
  float k = fract(aSeed.w * 5.3 + cyc * 0.17);
  if (pud < 0.5 && k > 0.3) kill = 1.0;
  if (k > 0.2 + 0.8 * uRain) kill = 1.0;
  if (p.x > 29.7 || wInside(p + vec3(0.0, 0.2, 0.0))) kill = 1.0;
  float sz = mix(0.04, 0.08, aSeed.z) * mix(0.65, 1.0, pud);
  float wd = sz * (0.7 + 1.5 * life), ht = sz * (0.4 + 1.3 * sin(life * 3.14159));
  vec3 toP = p - cameraPosition; float dist = length(toP);
  vec3 side = normalize(vec3(toP.z, 0.0, -toP.x));
  vec3 wp = p + side * (wd * uv.x * 2.0) + vec3(0.0, ht * uv.y + 0.004, 0.0);
  float c = dot(toP / max(dist, 1e-3), uSunDir);
  vec3 world = vec3(wp.x, wp.y, -wp.z);
  vWorldPos = world;
  vNormal = vec3(0.0, 1.0, 0.0);
  vUV = uv;
  vColor = vec4(uAmb * 1.4 + uSunCol * wPhase(c) * 0.8, (1.0 - life) * (1.0 - smoothstep(11.0, 15.0, dist)) * mix(0.5, 1.0, pud));
  vTangent = vec4(1.0, 0.0, 0.0, 1.0);
  vLife = life;
  gl_Position = kill > 0.5 ? vec4(2.0, 2.0, 2.0, 1.0) : pot_ViewProj * vec4(world, 1.0);
}

files.mech/foe.ts:
/**
 * 机甲的模拟积木：mechFoe（感知、警戒、攻击令牌与开火）、mechGull（飞行、避障、坠毁爆炸）、
 * mechHound（地面移动、扑击、倒地）、mechBolt（弹道）、mechBoom（爆炸，只有表现）。
 * 逐行照搬 saltline 原版敌人（坐标用 Unity 系）；目标按标签找，伤害走 fps 的 damage。
 *
 * 用到的 w.vars：mechFrozen（为真时整体冻结，如标题画面；暂停用 flow 叠加状态，模拟不走）、mechHostile（为假时不感知、不开火、不伤人）、mechTokenGap（攻击令牌间隔）。
 * 发出的 World 事件：mechAlert { entity, pos }（从巡逻或搜索转入交战）。
 */
import { defineBlock, definePrefab, type Vec3, type World, type EntityData } from '@pot/core'
import { damage } from '@pot/kit/fps'
import { angleDelta, clamp, dist, dist2d, jitter, lerp, norm, RAD, segmentDistance, sub, yawOf } from '@pot/kit/realistic/math'
import type { EnemyType } from './models'
import { chestOf, eyeOf, findTarget, hpOf } from './target'
import { boltView, boomView, foeView } from './look'

type Mode = 'patrol' | 'combat' | 'search' | 'dying'

/** 开火口（局部坐标，绕朝向旋转；原版飞鸥 d.muzzle = (0, -.12, .17)） */
const MUZZLE: Record<EnemyType, Vec3> = { hound: [0, 0.97, 0.45], gull: [0, -0.12, 0.17] }

export const FOE_PROPS = {
  kind: 'hound' as EnemyType,
  /** 生成时直接搜索目标 */
  pursuit: false,
  /** 目标的标签 */
  target: 'player',
  /** 视线、避障、弹道的射线层 */
  layers: ['default', 'bullet'],
  /** 地坪：x ≤ maxX 为 y，之外为海面 sea */
  ground: { y: 0, maxX: 30, sea: -1.6 },
  /** 视距、视锥（度）、看丢多久转搜索、搜索多久、听觉半径、同时开火数（人多时 crowd，存活数 ≥ crowdAt 算人多）、令牌间隔 */
  sense: { range: 45, cone: 200, lose: 4, search: 8, hear: 45, tokens: 2, crowd: 3, crowdAt: 6, gap: 1.25 },
}

export const GULL_PROPS = {
  boltDamage: 7, boltSpeed: 70, burst: 3, burstGap: 0.12, telegraph: 0.55, cooldown: [1.9, 3.3] as [number, number],
  rangeMin: 12, rangeMax: 25, altMin: 4, altMax: 8, maxSpeed: 8, patrolSpeed: 3, accel: 11,
  spreadFar: 0.065, spreadNear: 0.018, fireRange: 42, explodeRadius: 3, explodeDamage: 30,
}

export const HOUND_PROPS = {
  shotDamage: 5, shotSpeed: 55, burst: 4, burstGap: 0.11, telegraph: 0.5, cooldown: [1.8, 3] as [number, number],
  runSpeed: 4.5, stalkSpeed: 2, patrolSpeed: 1.5, accel: 7, turnRate: 2.5, rangeMin: 8, rangeMax: 18,
  spreadFar: 0.12, spreadNear: 0.045, lungeRange: 3, lungeDamage: 15, lungeCooldown: 3.5, lungeSpeed: 9.5, fireRange: 30,
  /** 地面移动的身体（w.move） */
  body: { radius: 0.45, height: 1.3, stepUp: 0.5, layers: ['default'] },
}

export const BOLT_PROPS = {
  vel: [0, 0, 1] as Vec3,
  damage: 0,
  kind: 'gull' as EnemyType,
  target: 'player',
  layers: ['default', 'bullet'],
  /** 开火声的音高（开火时定好，表现播放） */
  pitch: 1,
}

/** 种类积木（射击参数在这里） */
const gun = (e: EntityData, f: any): any => (f.kind === 'gull' ? e.b.mechGull : e.b.mechHound)
const planeY = (f: any, x: number) => (x <= f.ground.maxX ? f.ground.y : f.ground.sea)

/** 每步统计一次存活数与持有令牌数，并让令牌间隔走一步（只是缓存，不是状态） */
const tallies = new WeakMap<object, { tick: number; alive: number; tokens: number }>()
function tokens(w: World) {
  let t = tallies.get(w)
  if (!t) tallies.set(w, (t = { tick: -1, alive: 0, tokens: 0 }))
  if (t.tick !== w.tick) {
    t.tick = w.tick
    t.alive = t.tokens = 0
    for (const x of w.query()) {
      const f = x.b.mechFoe
      if (!f) continue
      if (f.mode !== 'dying') t.alive++
      if (f.token) t.tokens++
    }
    w.vars.mechTokenGap = Math.max(0, w.vars.mechTokenGap - w.dt)
  }
  return t
}

function releaseToken(f: any, w: World) {
  if (!f.token) return
  f.token = false
  w.vars.mechTokenGap = f.sense.gap
}

function enterCombat(f: any, e: EntityData, w: World, at: Vec3) {
  const was = f.mode
  f.mode = 'combat'
  f.lastKnown = [...at]
  f.lost = 0
  if (was === 'patrol' || was === 'search') w.emit('mechAlert', { entity: e, pos: [...e.pos] })
}

const sightFrom = (f: any, e: EntityData): Vec3 => (f.kind === 'gull' ? [...e.pos] as Vec3 : [e.pos[0], e.pos[1] + 1.1, e.pos[2]])

function canSee(f: any, e: EntityData, w: World, eye: Vec3, d: number) {
  const S = f.sense
  if (d > S.range) return false
  if (f.mode !== 'combat' && Math.abs(angleDelta(f.yaw, yawOf(sub(eye, e.pos)))) > S.cone / 2) return false
  const from = sightFrom(f, e)
  const hit = w.raycast(from, sub(eye, from), d, { layers: f.layers })
  return !hit || hit.dist > d - 0.4
}

function fire(f: any, e: EntityData, w: World, target: Vec3) {
  const T = gun(e, f), y = f.yaw * RAD, gull = f.kind === 'gull'
  const [mx, my, mz] = MUZZLE[f.kind as EnemyType]
  const origin: Vec3 = [e.pos[0] + Math.sin(y) * mz + Math.cos(y) * mx, e.pos[1] + my, e.pos[2] + Math.cos(y) * mz - Math.sin(y) * mx]
  const spread = lerp(T.spreadNear, T.spreadFar, clamp(dist(origin, target) / T.fireRange, 0, 1))
  const dir = jitter(norm(sub(target, origin)), spread, () => w.rand())
  if (gull) for (let k = 0; k < 3; k++) f.vel[k] -= dir[k] * 0.35
  const speed = gull ? T.boltSpeed : T.shotSpeed
  const pitch = 0.9 + w.rand() * 0.2
  w.spawn('bolt', {
    at: origin,
    mechBolt: { vel: [dir[0] * speed, dir[1] * speed, dir[2] * speed], damage: gull ? T.boltDamage : T.shotDamage, kind: f.kind, target: f.target, layers: f.layers, pitch },
  })
  f.fired = w.tick
}

/** 死亡的模拟部分；掉旋翼、熄灯等由表现看到 mode 变成 dying 后自己做 */
function die(f: any, w: World, dir?: Vec3) {
  releaseToken(f, w)
  f.mode = 'dying'
  f.dyingT = 0
  f.attack = 'idle'
  if (f.kind === 'gull') {
    // 原版：上抛 1.5，沿弹道再推 2.5，之后自旋坠落
    f.vel[1] += 1.5
    if (dir) for (let k = 0; k < 3; k++) f.vel[k] += dir[k] * 2.5
  } else {
    f.vel[0] *= 0.3; f.vel[2] *= 0.3
  }
}

/** 爆炸：火球（表现在 mechBoom），半径内按距离伤害目标，四倍半径内震屏 */
function explode(w: World, f: any, pos: Vec3, amount: number, radius: number) {
  w.spawn('boom', { at: [...pos] })
  const t = findTarget(w, f.target)
  if (!t || amount <= 0) return
  const d = dist(chestOf(t), pos)
  if (d < radius) damage(w, t, Math.round(amount * (1 - (d / radius) * 0.5)))
  const c = t.b.cameraFps
  if (c && d < radius * 4) c.shake = Math.min(1, c.shake + (1 - d / (radius * 4)) * 0.6)
}

/** 共用：感知、警戒状态与攻击循环（先于移动） */
export const mechFoe = defineBlock({
  name: 'mechFoe',
  about: '机甲共用：视线与听觉、巡逻/交战/搜索状态、攻击令牌与开火。kind 为 gull 或 hound（射击参数在 mechGull、mechHound），pursuit 为生成时直接搜索目标',
  props: FOE_PROPS,
  state: {
    mode: 'patrol' as Mode, yaw: 0, vel: [0, 0, 0] as Vec3, home: [0, 0, 0] as Vec3, goal: [0, 0, 0] as Vec3, goalT: 0,
    lastKnown: [0, 0, 0] as Vec3, lost: 0, searchT: 0, seeing: false, losT: 0,
    attack: 'idle' as 'idle' | 'telegraph' | 'burst', attackT: 0, shots: 0, cooldown: 0, token: false,
    orbit: 1, dyingT: 0, anim: 0, flash: 0,
    /** 最近一次开火的步号（表现据此做后坐） */
    fired: -1,
    /** 受击次数与最近一次的伤害、方向、是否弱点（表现据此做受击动画） */
    hits: 0, hitDmg: 0, hitDir: [0, 0, 0] as Vec3, hitWeak: false,
  },
  init(me, e, w) {
    const T = gun(e, me), t = findTarget(w, me.target)
    me.yaw = w.rand() * 360
    me.home = [...e.pos] as Vec3
    me.goal = [...e.pos] as Vec3
    me.lastKnown = t ? [...t.pos] as Vec3 : [...e.pos] as Vec3
    me.mode = me.pursuit ? 'search' : 'patrol'
    me.searchT = me.sense.search * 2
    me.losT = w.rand() * 0.2
    me.cooldown = lerp(T.cooldown[0], T.cooldown[1], w.rand())
    me.orbit = w.rand() < 0.5 ? -1 : 1
    me.anim = w.rand() * 10
  },
  step(me, e, w) {
    const t = findTarget(w, me.target)
    if (w.vars.mechFrozen || !t) return
    const T = gun(e, me), S = me.sense, dt = w.dt
    me.anim += dt
    me.flash = Math.max(0, me.flash - dt)
    if (me.mode === 'dying') { me.dyingT += dt; return }
    const fighting = !!w.vars.mechHostile
    const eye = eyeOf(t), tk = tokens(w)
    // 感知
    const d = dist(sightFrom(me, e), eye)
    me.losT -= dt
    if (me.losT <= 0) {
      me.losT = 0.18 + w.rand() * 0.08
      me.seeing = fighting && hpOf(t) > 0 && canSee(me, e, w, eye, d)
    }
    if (me.seeing) {
      if (me.mode !== 'combat') enterCombat(me, e, w, t.pos)
      me.lastKnown = [...t.pos] as Vec3
      me.lost = 0
    } else if (me.mode === 'combat') {
      me.lost += dt
      if (me.lost > S.lose) { me.mode = 'search'; me.searchT = S.search }
    }
    if (me.mode === 'search') {
      me.searchT -= dt
      if (me.searchT <= 0) { me.mode = 'patrol'; me.home = [...e.pos] as Vec3 }
    }
    // 攻击循环：预警 → 连发；同时开火的数量受令牌限制
    const facing = me.kind !== 'gull' || Math.abs(angleDelta(me.yaw, yawOf(sub(t.pos, e.pos)))) < 20
    const inRange = me.mode === 'combat' && me.seeing && d < T.fireRange
    if (me.attack === 'idle') {
      me.cooldown -= dt
      const max = tk.alive >= S.crowdAt ? S.crowd : S.tokens
      if (inRange && facing && me.cooldown <= 0 && !me.token && tk.tokens < max && w.vars.mechTokenGap <= 0) {
        me.token = true
        tk.tokens++
        w.vars.mechTokenGap = S.gap * 0.5
        me.attack = 'telegraph'
        me.attackT = T.telegraph
      }
    } else if (me.attack === 'telegraph') {
      me.attackT -= dt
      if (!inRange) { me.attack = 'idle'; me.cooldown = 0.6; releaseToken(me, w) }
      else if (me.attackT <= 0) { me.attack = 'burst'; me.shots = T.burst; me.attackT = 0 }
    } else {
      me.attackT -= dt
      if (!fighting) { me.shots = 0 } // 不再敌对（如玩家已死）：不对着尸体打完连发
      else if (me.attackT <= 0 && me.shots > 0) { fire(me, e, w, chestOf(t)); me.shots--; me.attackT = T.burstGap }
      if (me.shots <= 0) { me.attack = 'idle'; me.cooldown = lerp(T.cooldown[0], T.cooldown[1], w.rand()); releaseToken(me, w) }
    }
  },
  view: foeView,
})

/**
 * 飞鸥飞行（原版 x() 的移动部分，Unity 坐标；公式对 z 镜像对称）：
 * 目标点（交战绕目标盘旋 / 搜索绕最后位置 / 巡逻绕出生点）→ PD 加速度 + 三向探测避障 → 限加速度、限速 → 逐轴碰撞 → 离地 ≥ 1.1。
 */
export const mechGull = defineBlock({
  name: 'mechGull',
  about: '机械飞鸥：盘旋飞行、射线避障、限高；死亡后坠落并爆炸。属性为射击与飞行参数，配 mechFoe（kind: gull）',
  order: 1,
  props: GULL_PROPS,
  state: {
    orbitA: 0, orbitR: 0, patrolR: 0, alt: 0, flipT: 0, avoid: [0, 0, 0] as Vec3, ceil: 1e9, ceilT: 0, feeler: 0, phase: 0,
    /** 本步加速度（表现的机身姿态用） */
    acc: [0, 0, 0] as Vec3,
  },
  init(me, _e, w) {
    me.orbitR = me.rangeMin + 2 + w.rand() * (me.rangeMax - me.rangeMin - 5)
    me.alt = me.altMin + 0.8 + w.rand() * (me.altMax - me.altMin - 1.6)
    me.patrolR = 4 + w.rand() * 5
    me.phase = w.rand() * 6.283
    me.orbitA = w.rand() * 6.283
    me.flipT = 3 + w.rand() * 4
  },
  step(me, e, w) {
    const f = e.b.mechFoe
    const t = f && findTarget(w, f.target)
    if (w.vars.mechFrozen || !t) return
    const dt = w.dt, v: Vec3 = f.vel, pos: Vec3 = e.pos, RAY = { layers: f.layers }
    if (f.mode === 'dying') {
      // 原版：重力 9.5、水平阻尼；撞到东西、落地/落海或 5 秒后爆炸
      v[1] -= 9.5 * dt
      v[0] *= 1 - 0.4 * dt; v[2] *= 1 - 0.4 * dt
      const b = Math.hypot(v[0], v[1], v[2])
      let done = f.dyingT > 5 || pos[1] < -3
      if (!done && b > 0.01) {
        const h = w.raycast(pos, v, b * dt + 0.3, RAY)
        if (h) { e.pos = [h.point[0] + h.normal[0] * 0.2, h.point[1] + h.normal[1] * 0.2, h.point[2] + h.normal[2] * 0.2]; done = true }
      }
      if (!done) {
        for (let k = 0; k < 3; k++) pos[k] += v[k] * dt
        const py = planeY(f, pos[0])
        if (pos[1] <= py + 0.2) { pos[1] = py + 0.2; done = true }
      }
      if (done) {
        explode(w, f, e.pos, w.vars.mechHostile ? me.explodeDamage : 0, me.explodeRadius)
        w.destroy(e)
      }
      return
    }
    const combat = f.mode === 'combat', hp = e.b.health, hurt = !!hp && hp.hp < hp.max * 0.5, an = f.anim, lk: Vec3 = f.lastKnown
    let M = me.patrolSpeed, tx: number, ty: number, tz: number
    if (combat) {
      M = me.maxSpeed
      me.flipT -= dt
      if (me.flipT <= 0) {
        me.flipT = 3 + w.rand() * 5
        if (w.rand() < 0.6) f.orbit = -f.orbit
        me.orbitR = clamp(me.orbitR + (w.rand() - 0.5) * 6, me.rangeMin + 1, me.rangeMax - 2)
      }
      if (f.lost > 1.5) {
        tx = lk[0]; tz = lk[2]; ty = lk[1] + me.alt + 1
        me.orbitA = Math.atan2(pos[2] - lk[2], pos[0] - lk[0])
      } else {
        me.orbitA += f.orbit * (f.attack !== 'idle' ? 0.9 : 3.6) / me.orbitR * dt
        tx = t.pos[0] + Math.cos(me.orbitA) * me.orbitR; tz = t.pos[2] + Math.sin(me.orbitA) * me.orbitR; ty = t.pos[1] + me.alt
      }
    } else if (f.mode === 'search') {
      M = 5.5
      me.orbitA += 0.5 * dt
      tx = lk[0] + Math.cos(me.orbitA) * 4.5; tz = lk[2] + Math.sin(me.orbitA) * 4.5; ty = lk[1] + Math.min(me.alt, 5.5)
    } else {
      me.orbitA += 0.28 * dt * f.orbit
      tx = f.home[0] + Math.cos(me.orbitA) * me.patrolR; tz = f.home[2] + Math.sin(me.orbitA) * me.patrolR; ty = f.home[1]
    }
    ty = Math.max(2.2, Math.min(ty, me.ceil))
    const acc: Vec3 = [(tx - pos[0]) * 2.2 - v[0] * 2.4, (ty - pos[1]) * 5 - v[1] * 3.6, (tz - pos[2]) * 2.2 - v[2] * 2.4]
    const av = me.avoid
    me.feeler = (me.feeler + 1) % 3
    const z = Math.hypot(v[0], v[2])
    if (me.feeler === 0 && z > 0.6) {
      const P = 2.2 + z * 0.5
      const h = w.raycast(pos, [v[0] / z, 0, v[2] / z], P, RAY)
      if (h) {
        const Y = 1 - h.dist / P
        av[0] = h.normal[0] * 26 * Y; av[1] = h.normal[1] * 26 * Y + 9 * Y; av[2] = h.normal[2] * 26 * Y
        if (Y > 0.5) { f.orbit = -f.orbit; me.flipT = 2.5 }
      }
    } else if (me.feeler === 1) {
      const h = w.raycast(pos, [0, -1, 0], 2.4, RAY)
      if (h) av[1] += (2.4 - h.dist) * 10
    } else if (me.feeler === 2) {
      me.ceilT -= dt * 3
      if (me.ceilT <= 0) {
        me.ceilT = 0.35
        const h = w.raycast(pos, [0, 1, 0], 4, RAY)
        me.ceil = h ? pos[1] + h.dist - 1.3 : 1e9
      }
    }
    const decay = Math.exp(-6 * dt)
    for (let k = 0; k < 3; k++) { acc[k] += av[k]; av[k] *= decay }
    if (hurt) {
      acc[0] += Math.sin(an * 7.3 + me.phase) * 5; acc[2] += Math.cos(an * 6.1 + me.phase) * 5; acc[1] += Math.sin(an * 9.7) * 3
    }
    const H = Math.hypot(acc[0], acc[1], acc[2])
    if (H > me.accel) for (let k = 0; k < 3; k++) acc[k] *= me.accel / H
    for (let k = 0; k < 3; k++) v[k] += acc[k] * dt
    const O = Math.hypot(v[0], v[1], v[2])
    if (O > M) for (let k = 0; k < 3; k++) v[k] *= M / O
    // 逐轴碰撞：撞上则反弹 .25 并记一次反向推力
    for (let k = 0; k < 3; k++) {
      const V = v[k]
      if (Math.abs(V) < 0.02) continue
      const Y = V > 0 ? 1 : -1, L = k === 1 ? 0.35 : 0.62
      const dir: Vec3 = [0, 0, 0]; dir[k] = Y
      const h = w.raycast(pos, dir, Math.abs(V) * dt + L, RAY)
      if (h) {
        v[k] = -V * 0.25
        av[k] -= Y * 8
        if (h.dist < L) pos[k] -= Y * (L - h.dist)
      }
    }
    for (let k = 0; k < 3; k++) pos[k] += v[k] * dt
    // 原版 groundHeight(x, z, y + .5) + 1.1
    const g = w.raycast([pos[0], pos[1] + 0.5, pos[2]], [0, -1, 0], 60, RAY)
    const floor = Math.max(g ? g.point[1] : -Infinity, planeY(f, pos[0])) + 1.1
    if (pos[1] < floor) { pos[1] = floor; if (v[1] < 0) v[1] = 0 }
    // 朝向：交战/搜索时看目标（或最后位置），否则看飞行方向；转速 3.2 rad/s
    let q = f.yaw
    if (combat || f.mode === 'search') q = yawOf(sub(combat && f.lost < 1.5 ? t.pos : lk, pos))
    else if (z > 0.4) q = yawOf(v)
    const turn = 3.2 / RAD * dt
    f.yaw += clamp(angleDelta(f.yaw, q), -turn, turn)
    me.acc = acc
  },
})

/** 猎犬：巡逻游走、交战时绕目标侧移或追击、近身扑击；撞墙临时绕行 */
export const mechHound = defineBlock({
  name: 'mechHound',
  about: '机械猎犬：地面移动（w.move）、绕行、扑击；死亡后滑行倒地、下沉回收。属性为射击与移动参数，配 mechFoe（kind: hound）',
  order: 1,
  props: HOUND_PROPS,
  state: { grounded: true, yawRate: 0, lunge: 0, lungeCd: 0, detour: 0, detourT: 0 },
  step(me, e, w) {
    const f = e.b.mechFoe
    const t = f && findTarget(w, f.target)
    if (w.vars.mechFrozen || !t) return
    const dt = w.dt, v: Vec3 = f.vel
    if (f.mode === 'dying') {
      // 原版：滑行减速、倒地；6.5 秒后残骸以 .22m/s 下沉 3.2 秒再回收（原版不爆炸）
      const k = Math.exp(-5 * dt)
      v[0] *= k; v[2] *= k
      e.pos[0] += v[0] * dt; e.pos[2] += v[2] * dt
      if (f.dyingT > 6.5) e.pos[1] -= 0.22 * dt
      if (f.dyingT > 9.7) w.destroy(e)
      return
    }
    me.detourT = Math.max(0, me.detourT - dt)
    f.goalT -= dt
    const toP = sub(t.pos, e.pos)
    const hd = Math.hypot(toP[0], toP[2]) || 1
    let target: Vec3 = f.goal
    let speed = me.patrolSpeed
    if (f.mode === 'combat') {
      if (hd > me.rangeMax || !f.seeing) { target = f.lastKnown; speed = me.runSpeed }
      else if (hd < me.rangeMin) { target = [e.pos[0] - toP[0] / hd * 3, 0, e.pos[2] - toP[2] / hd * 3]; speed = me.stalkSpeed }
      else {
        target = [e.pos[0] - toP[2] / hd * f.orbit * 3, 0, e.pos[2] + toP[0] / hd * f.orbit * 3]
        speed = me.stalkSpeed
        if (f.goalT <= 0) { f.goalT = 1.5 + w.rand() * 2; if (w.rand() < 0.5) f.orbit *= -1 }
      }
      me.lungeCd = Math.max(0, me.lungeCd - dt)
      if (hd < me.lungeRange && me.lungeCd <= 0 && me.lunge <= 0) {
        me.lunge = 0.35
        me.lungeCd = me.lungeCooldown
        v[0] = toP[0] / hd * me.lungeSpeed; v[2] = toP[2] / hd * me.lungeSpeed; v[1] = 3
      }
    } else if (f.mode === 'search') {
      target = f.lastKnown
      speed = me.runSpeed * 0.7
    } else if (f.goalT <= 0 || dist2d(e.pos, f.goal) < 1) {
      f.goalT = 4 + w.rand() * 4
      const a = w.rand() * Math.PI * 2, r = 2 + w.rand() * 7
      f.goal = [f.home[0] + Math.cos(a) * r, 0, f.home[2] + Math.sin(a) * r]
    }
    if (me.lunge > 0) {
      me.lunge -= dt
      if (dist2d(e.pos, t.pos) < 1.2 && Math.abs(e.pos[1] - t.pos[1]) < 1.5) {
        me.lunge = 0
        if (w.vars.mechHostile) damage(w, t, me.lungeDamage, e)
        v[0] *= -0.3; v[2] *= -0.3
      }
    } else {
      // 转向目标（绕行时把期望速度转 detour 度），按加速度逼近
      const dx = target[0] - e.pos[0], dz = target[2] - e.pos[2], l = Math.hypot(dx, dz)
      const sp = Math.min(speed, l * 1.5)
      let tx = l > 0.01 ? dx / l * sp : 0, tz = l > 0.01 ? dz / l * sp : 0
      if (me.detourT > 0) {
        const a = me.detour * RAD, c = Math.cos(a), s = Math.sin(a)
        ;[tx, tz] = [tx * c + tz * s, -tx * s + tz * c]
      }
      const k = Math.min(1, me.accel * dt / Math.max(0.001, speed))
      v[0] += (tx - v[0]) * k
      v[2] += (tz - v[2]) * k
    }
    // 原版：机身只沿自身前方移动；期望朝向 = 速度方向（停下且交战时朝目标），转速限 turnRate（扑击时 ×2）
    const hs = Math.hypot(v[0], v[2])
    const want = me.lunge > 0 ? yawOf(toP) : hs > 0.3 ? yawOf(v) : f.mode === 'combat' && f.seeing ? yawOf(toP) : f.yaw
    const F = clamp(angleDelta(f.yaw, want) * 6, -me.turnRate * 57.3, me.turnRate * 57.3) * (me.lunge > 0 ? 2 : 1)
    me.yawRate += (F - me.yawRate) * (1 - Math.exp(-10 * dt))
    f.yaw += me.yawRate * dt
    const fwd = me.lunge > 0 ? 1 : Math.max(0, Math.cos(angleDelta(f.yaw, want) * RAD))
    v[0] = Math.sin(f.yaw * RAD) * hs * fwd
    v[2] = Math.cos(f.yaw * RAD) * hs * fwd
    v[1] -= 21 * dt
    const B = me.body, mover = { vel: v, grounded: me.grounded }
    const res = w.move(e, mover, { radius: B.radius, height: B.height, stepUp: B.stepUp, layers: B.layers, ground: { y: f.ground.y, maxX: f.ground.maxX } })
    me.grounded = mover.grounded
    if (res.hitWall && me.detourT <= 0) { me.detour = (w.rand() < 0.5 ? -1 : 1) * 75; me.detourT = 0.9 }
    if (e.pos[1] < -3) { e.pos = [f.home[0], f.home[1], f.home[2]]; f.vel = [0, 0, 0] }
  },
})

/** 弹道：飞行、寿命、打中目标、撞墙（不用系统 projectile/lifetime：它们不认 mechFrozen） */
export const mechBolt = defineBlock({
  name: 'mechBolt',
  about: '机甲弹道：按 vel 飞行 1.6 秒，扫过目标躯干或头部时造成 damage，撞到 layers 里的碰撞盒消失',
  order: 2,
  props: BOLT_PROPS,
  state: { life: 1.6 },
  step(me, e, w) {
    if (w.vars.mechFrozen) return
    const t = findTarget(w, me.target), v = me.vel, dt = w.dt
    const prev: Vec3 = [e.pos[0], e.pos[1], e.pos[2]]
    for (let k = 0; k < 3; k++) e.pos[k] += v[k] * dt
    me.life -= dt
    let dead = me.life <= 0
    if (!dead && t && w.vars.mechHostile && hpOf(t) > 0 && (segmentDistance(chestOf(t), prev, e.pos) < 0.45 || segmentDistance(eyeOf(t), prev, e.pos) < 0.3)) {
      damage(w, t, me.damage, e)
      dead = true
    }
    if (!dead && w.raycast(prev, v, Math.hypot(v[0], v[1], v[2]) * dt, { layers: me.layers })) dead = true
    if (dead) w.destroy(e)
  },
  view: boltView,
})

