/** 清空机甲、弹道与爆炸（销毁在本步末尾生效），令牌间隔归零 */
export function mechClear(w: World) {
  for (const e of w.query()) if (e.b.mechFoe || e.b.mechBolt || e.b.mechBoom) w.destroy(e)
  w.vars.mechTokenGap = 0
}

