const Bv = [31, 21.5, 12.5], Fv = [5.6, 5.3, 5], Lv = [3.2, 3.1, 3], am = [12.5, 10, 7.6], lm = [16, 11, 6.6], dC = [3, 2.6, 2.2], kf = [36, 27, 16], gl = [20, 14, 8.4], Df = [4.8, 4.5, 4.2], pC = [30, 9.5, 2.2], E_ = [5, 6.9, 9], mC = [30, 9.5, 2.2], gC = [26, 26, 25]
