// 原版粒子顶点着色器（pretty.js HR）机械移植。原版是实例化四边形；这里每粒子 4 个顶点、中心相同，
// 由 fx.ts 打包（自定义顶点属性，Float32 原样传，不经色彩空间转换）：
//   pot_Position = 中心，pot_UV.x = 角点 0..3
//   aAxis = mode 1 时 (拉伸轴 xyz, size)，否则 (roll, 0, 0, size)
//   aCol  = rgb（HDR，可大于 1）+ a
//   aMisc = (frame, mode, age, shade)
// 全部在 Unity 世界坐标下计算（相机右/上取自 pot_View 前两行，与原版 viewMatrix 写法相同）。
#include <pot/varyings>

uniform vec2 uAtlas;

out vec3 vOff;
out vec3 vToCam;
out vec3 vInfo;     // 视深, age, shade
out vec3 vT;
out vec3 vB;
out float vSoftD;   // 软粒子淡出距离（原版 clamp(size·.4, .04, .7)）

void main() {
  float k = floor(pot_UV.x + 0.5);
  float frame = floor(aMisc.x + 0.5);
  float mode = floor(aMisc.y + 0.5);
  vec2 c = vec2((k > 0.5 && k < 2.5) ? 0.5 : -0.5, k > 1.5 ? 0.5 : -0.5);
  vec3 center = pot_Position; float size = aAxis.w;
  vec3 camR = vec3(pot_View[0][0], pot_View[1][0], pot_View[2][0]);
  vec3 camU = vec3(pot_View[0][1], pot_View[1][1], pot_View[2][1]);
  vec3 toCam = pot_CameraPos.xyz - center; float dist = length(toCam); toCam /= max(dist, 1e-4);
  float roll = mode > 0.5 && mode < 1.5 ? 0.0 : aAxis.x;
  float sn = sin(roll), cs = cos(roll);
  vec2 rc = vec2(c.x * cs - c.y * sn, c.x * sn + c.y * cs);
  vec3 off; float comp = 1.0;
  vec3 T, B;
  if (mode < 0.5) {
    off = (camR * rc.x + camU * rc.y) * size;
    T = camR * cs + camU * sn; B = camU * cs - camR * sn;
  } else if (mode < 1.5) {
    float uPx = 2.0 * pot_Camera.z * pot_Resolution.w;
    vec3 axis = aAxis.xyz;
    float len = length(axis); vec3 d = axis / max(len, 1e-5);
    vec3 side = cross(d, toCam); float sl = length(side); side = sl > 1e-3 ? side / sl : camR;
    float w = max(size, dist * uPx * 1.4); comp = size / w;
    off = d * (c.x * max(len, w)) + side * (c.y * w);
    T = d; B = side;
  } else {
    vec3 n = vec3(0.0, 1.0, 0.0);
    vec3 t = vec3(0.0, 0.0, -1.0);
    vec3 b = cross(n, t);
    off = (t * rc.x + b * rc.y) * size;
    T = t * cs + b * sn; B = b * cs - t * sn;
  }
  vec3 world = center + off;
  vec4 mv = pot_View * vec4(world, 1.0);
  gl_Position = pot_ViewProj * vec4(world, 1.0);
  float col = mod(frame, uAtlas.x), row = floor(frame / uAtlas.x);
  vUV = (vec2(col, row) + c + 0.5) / uAtlas;
  vColor = vec4(aCol.rgb * comp, aCol.a);
  vWorldPos = world;
  vNormal = toCam;
  vTangent = vec4(T, 1.0);
  vOff = off / max(size, 1e-4);
  vToCam = toCam;
  vInfo = vec3(abs(mv.z), mode < 0.5 ? aMisc.z : 0.0, mode < 0.5 ? aMisc.w : 1.0);
  vT = T; vB = B;
  vSoftD = clamp(size * 0.4, 0.04, 0.7);
}

files.realistic/shaders/fx_add.frag:
// 原版加法粒子片元（pretty.js WR）机械移植：水珠、涟漪环、火花、闪光。绑定 blend: add（alpha 恒为 1 → One, One）。
// softFade：贴近背后不透明表面时淡出（读场景深度，需透明队列）。
#include <pot/varyings>
#include <pot/depth>

uniform sampler2D uTex;

in float vSoftD;

out vec4 fragColor;

void main() {
  float t = texture(uTex, vUV).r;
  float k = t * vColor.a * pot_SoftFade(vWorldPos, vSoftD);
  if (k < 0.002) discard;
  fragColor = vec4(vColor.rgb * k, 1.0);
}

files.realistic/shaders/fx_lit.frag:
// 原版受光粒子片元（pretty.js VR）机械移植：烟团 / 水柱 / 水雾。预乘 alpha 输出（绑定 blend: premultiplied）。
// softFade 读场景深度（pot/depth，透明队列）；色调映射交给全局后处理。
#include <pot/varyings>
#include <pot/depth>

uniform sampler2D uTex;
uniform vec3 uSun, uSunDir, uAmbLo, uAmbHi;

in vec3 vOff;
in vec3 vToCam;
in vec3 vInfo;
in vec3 vT;
in vec3 vB;
in float vSoftD;

out vec4 fragColor;

void main() {
  vec4 t = texture(uTex, vUV);
  float er = vInfo.y * 0.45;
  float a = smoothstep(er, er + (vInfo.z > 1.5 ? 0.38 : 0.6), t.a) * vColor.a;
  a *= pot_SoftFade(vWorldPos, vSoftD) * smoothstep(0.2, 0.9, vInfo.x);
  if (a < 0.004) discard;
  vec3 V = normalize(vToCam);
  vec3 q = vOff * 2.0; float r2 = min(dot(q, q), 1.0);
  vec3 Ns = q + V * (sqrt(1.0 - r2) * 0.9 + 0.05);
  vec2 tn = t.rg * 2.0 - 1.0;
  vec3 Nb = vT * tn.x + vB * tn.y + V * sqrt(max(1.0 - dot(tn, tn), 0.0));
  vec3 N = normalize(Ns * 0.55 + Nb);
  float wrap = clamp((dot(N, uSunDir) + 0.45) / 1.45, 0.0, 1.0);
  float back = pow(clamp(dot(-V, uSunDir), 0.0, 1.0), 5.0);
  float thin = 1.0 - t.b * smoothstep(0.0, 0.5, a);
  float hot = step(1.5, vInfo.z), shade = vInfo.z - 2.0 * hot;
  vec3 sun = uSun * (wrap * wrap * 0.85 + back * (0.15 + 1.3 * thin)) * shade;
  vec3 amb = mix(uAmbLo, uAmbHi, N.y * 0.5 + 0.5) * (1.0 - 0.35 * t.b);
  vec3 col = vColor.rgb * (amb + sun);
  if (hot > 0.5) {
    float lump = clamp(dot(tn, vec2(0.6, 0.8)) * 0.6 + 0.5, 0.0, 1.0);
    float core = t.b * t.b * smoothstep(0.15, 0.9, t.a);
    vec3 fire = vColor.rgb * (0.10 + 1.7 * core) * (0.45 + 1.1 * lump);
    col = vec3(0.045, 0.042, 0.04) * (amb + sun) + fire;
  }
  fragColor = vec4(col * a, a);
}

