// 后处理公共函数（移植自原版 Js/Og 片段）
#ifndef SALTLINE_POST_COMMON
#define SALTLINE_POST_COMMON
float ign(vec2 p) { return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715)))); }
float hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
float luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
vec3 toLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c)); }
vec3 toSRGB(vec3 c) { return mix(c * 12.92, 1.055 * pow(max(c, vec3(0.0)), vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c)); }

// 自动曝光：tAdapt 为 1x1 的 (平均亮度, 太阳可见度)
uniform sampler2D tAdapt;
uniform float uExposure, uKey, uMinE, uMaxE, uAuto;
float slExposure() {
  float a = texture(tAdapt, vec2(0.5)).r;
  return uExposure * mix(1.0, clamp(pow(uKey / max(a, 1e-4), 0.85), uMinE, uMaxE), uAuto);
}

// 太阳在屏幕上的位置：xy = uv，z = 在画面内的权重（相机背对太阳或远离画面边缘时为 0）
vec3 sunScreen() {
  vec3 s = pot_WorldToUv(pot_CameraPos.xyz + normalize(pot_SunDir.xyz) * 500.0);
  vec2 ndc = s.xy * 2.0 - 1.0;
  float on = s.z > 25.0 ? 1.0 - clamp((max(abs(ndc.x), abs(ndc.y)) - 1.0) / 0.3, 0.0, 1.0) : 0.0;
  return vec3(s.xy, on);
}
#endif

files.realistic/shaders/post/dirt.frag:
// 镜头污渍（原版 tA）：烘焙一次。噪声贴图换成程序化值噪声
#include <pot/post>
#include "common.glsl"
uniform float uAspect;
out vec4 fragColor;
float n2(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash12(i), b = hash12(i + vec2(1.0, 0.0)), c = hash12(i + vec2(0.0, 1.0)), d = hash12(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p, int n) {
  float a = 0.5, s = 0.0, norm = 0.0;
  for (int i = 0; i < 5; i++) {
    if (i >= n) break;
    s += a * n2(p);
    norm += a;
    p = mat2(1.6, 1.2, -1.2, 1.6) * p + 17.3;
    a *= 0.5;
  }
  return s / norm;
}
void main() {
  vec2 p = vUv * vec2(uAspect, 1.0);
  float acc = 0.0;
  for (int i = 0; i < 70; i++) {
    float fi = float(i);
    vec2 c = vec2(hash12(vec2(fi, 1.7)), hash12(vec2(fi, 9.2))) * vec2(uAspect, 1.0);
    float sz = mix(0.012, 0.085, pow(hash12(vec2(fi, 4.4)), 3.0));
    float r = length(p - c) / sz;
    float disc = smoothstep(1.0, 0.86, r) * (0.35 + 0.65 * smoothstep(0.35, 0.98, r));
    acc += disc * mix(0.15, 0.7, hash12(vec2(fi, 6.1)));
  }
  float smudge = fbm(vUv * vec2(5.0, 9.0) + 3.0, 5) * fbm(vUv * 2.3 + 9.0, 3);
  float streaks = pow(n2(vec2(vUv.x * 90.0, vUv.y * 2.0)), 4.0) * 0.25;
  float v = acc * 0.55 + smudge * 0.9 + streaks;
  v *= 0.45 + 0.9 * smoothstep(0.15, 0.75, length(vUv - 0.5));
  fragColor = vec4(vec3(v) * vec3(1.0, 0.96, 0.9), 1.0);
}

