// bloom 降采样（原版 J6）：13 tap，第一级用部分 Karis 平均压制亮点闪烁
#include <pot/post>
#include "common.glsl"
uniform sampler2D tSrc;
uniform float uFirst;
out vec4 fragColor;
vec2 texel;
vec3 s(vec2 o) { return min(max(texture(tSrc, vUv + o * texel).rgb, vec3(0.0)), vec3(400.0)); }
float kw(vec3 c) { return 1.0 / (1.0 + luma(c) * 0.08); }
void main() {
  texel = 1.0 / vec2(textureSize(tSrc, 0));
  vec3 a = s(vec2(-2.0, 2.0)), b = s(vec2(0.0, 2.0)), c = s(vec2(2.0, 2.0));
  vec3 d = s(vec2(-2.0, 0.0)), e = s(vec2(0.0, 0.0)), f = s(vec2(2.0, 0.0));
  vec3 g = s(vec2(-2.0, -2.0)), h = s(vec2(0.0, -2.0)), i = s(vec2(2.0, -2.0));
  vec3 j = s(vec2(-1.0, 1.0)), k = s(vec2(1.0, 1.0)), l = s(vec2(-1.0, -1.0)), m = s(vec2(1.0, -1.0));
  vec3 col;
  if (uFirst > 0.5) {
    vec3 g0 = (a + b + d + e) * 0.25, g1 = (b + c + e + f) * 0.25, g2 = (d + e + g + h) * 0.25, g3 = (e + f + h + i) * 0.25, g4 = (j + k + l + m) * 0.25;
    float w0 = kw(g0) * 0.125, w1 = kw(g1) * 0.125, w2 = kw(g2) * 0.125, w3 = kw(g3) * 0.125, w4 = kw(g4) * 0.5;
    col = (g0 * w0 + g1 * w1 + g2 * w2 + g3 * w3 + g4 * w4) / (w0 + w1 + w2 + w3 + w4);
  } else {
    col = e * 0.125 + (a + c + g + i) * 0.03125 + (b + d + f + h) * 0.0625 + (j + k + l + m) * 0.125;
  }
  fragColor = vec4(col, 1.0);
}

files.realistic/shaders/post/final.frag:
// 最终（原版 iA）：FXAA、轻度锐化、胶片颗粒、抖动（都在 sRGB 编码空间），最后转回线性写回相机画面
// （链生效时 URP 后处理关闭，最终 blit 负责线性 → sRGB）
#include <pot/post>
#include "common.glsl"
uniform sampler2D tSrc;
uniform float uGrain, uSharpen, uFxaa;
out vec4 fragColor;
void main() {
  vec2 uTexel = pot_ScreenSize.zw;
  vec4 M = texture(tSrc, vUv);
  vec3 col = M.rgb;
  vec4 NW = texture(tSrc, vUv + vec2(-1.0, -1.0) * uTexel), NE = texture(tSrc, vUv + vec2(1.0, -1.0) * uTexel);
  vec4 SW = texture(tSrc, vUv + vec2(-1.0, 1.0) * uTexel), SE = texture(tSrc, vUv + vec2(1.0, 1.0) * uTexel);
  float lMin = min(M.a, min(min(NW.a, NE.a), min(SW.a, SE.a)));
  float lMax = max(M.a, max(max(NW.a, NE.a), max(SW.a, SE.a)));
  float contrast = lMax - lMin;
  if (uFxaa > 0.5 && contrast > max(0.0312, lMax * 0.10)) {
    vec2 dir = vec2(-((NW.a + NE.a) - (SW.a + SE.a)), (NW.a + SW.a) - (NE.a + SE.a));
    float dirReduce = max((NW.a + NE.a + SW.a + SE.a) * 0.03125, 0.0078125);
    float rcp = 1.0 / (min(abs(dir.x), abs(dir.y)) + dirReduce);
    dir = clamp(dir * rcp, vec2(-8.0), vec2(8.0)) * uTexel;
    vec4 A = 0.5 * (texture(tSrc, vUv + dir * (1.0 / 3.0 - 0.5)) + texture(tSrc, vUv + dir * (2.0 / 3.0 - 0.5)));
    vec4 B = A * 0.5 + 0.25 * (texture(tSrc, vUv - dir * 0.5) + texture(tSrc, vUv + dir * 0.5));
    col = (B.a < lMin || B.a > lMax) ? A.rgb : B.rgb;
  }
  vec3 blur = (NW.rgb + NE.rgb + SW.rgb + SE.rgb) * 0.25;
  col += (M.rgb - blur) * uSharpen * (1.0 - smoothstep(0.04, 0.22, contrast));
  vec2 seed = gl_FragCoord.xy + fract(pot_Time.x * vec2(7.31, 3.17)) * vec2(311.7, 173.3);
  float g = hash12(seed) + hash12(seed + 57.3) - 1.0;
  float l = dot(col, vec3(0.299, 0.587, 0.114));
  col += g * uGrain * mix(1.0, 0.30, smoothstep(0.25, 0.9, l)) * (0.35 + 0.65 * smoothstep(0.0, 0.08, l));
  col += (hash12(gl_FragCoord.xy * 1.37 + 11.0) + hash12(gl_FragCoord.xy * 0.71 + 3.0) - 1.0) / 255.0;
  fragColor = vec4(toLinear(clamp(col, 0.0, 1.0)), 1.0);
}

files.realistic/shaders/post/grade.frag:
// 调色（原版 nA）：色差、ADS 边缘柔化、bloom/污渍/光斑、镜头眩光、曝光、ACES↔AgX、分离色调、S 曲线、
// 饱和度、暗角、受伤红边、淡出；另加雷电（原版在天空云层与体积光环境项里，这里按深度在后处理叠加）。
// 输出 sRGB 编码值（a = 亮度）到 rgba8 目标，供 final 做 FXAA
#include <pot/post>
#include <pot/lit>
#include "common.glsl"
uniform sampler2D tScene, tBloom, tBlur, tStreak, tDirt, tDepth, tVol;
uniform vec3 uSunCol, uFlashDir;
uniform float uBloom, uDirt, uStreak, uFlare, uCA, uVignette;
uniform float uDamage, uLowHealth, uAds, uFlash, uFade, uSaturation, uThunder, uAgxMix;
uniform float uLookPower, uLookSat;
uniform float uVol;  // 体积光强度（0 = 关闭，vol pass 也会被跳过）
out vec4 fragColor;

const mat3 SL_REC2020_TO_SRGB = mat3(vec3(1.6605, -0.1246, -0.0182), vec3(-0.5876, 1.1329, -0.1006), vec3(-0.0728, -0.0083, 1.1187));
const mat3 SL_SRGB_TO_REC2020 = mat3(vec3(0.6274, 0.0691, 0.0164), vec3(0.3293, 0.9195, 0.0880), vec3(0.0433, 0.0113, 0.8956));
vec3 slAgxContrast(vec3 x) { vec3 x2 = x * x; vec3 x4 = x2 * x2; return 15.5 * x4 * x2 - 40.14 * x4 * x + 31.96 * x4 - 6.868 * x2 * x + 0.4298 * x2 + 0.1191 * x - 0.00232; }
vec3 slAgx(vec3 color) {
  const mat3 inset = mat3(vec3(0.856627153315983, 0.137318972929847, 0.11189821299995), vec3(0.0951212405381588, 0.761241990602591, 0.0767994186031903), vec3(0.0482516061458583, 0.101439036467562, 0.811302368396859));
  const mat3 outset = mat3(vec3(1.1271005818144368, -0.1413297634984383, -0.14132976349843826), vec3(-0.11060664309660323, 1.157823702216272, -0.11060664309660294), vec3(-0.016493938717834573, -0.016493938717834257, 1.2519364065950405));
  const float minEv = -12.47393, maxEv = 4.026069;
  color = inset * (SL_SRGB_TO_REC2020 * color);
  color = clamp((log2(max(color, 1e-10)) - minEv) / (maxEv - minEv), 0.0, 1.0);
  color = slAgxContrast(color);
  float l = dot(color, vec3(0.2126, 0.7152, 0.0722));
  color = pow(max(color, vec3(0.0)), vec3(uLookPower));
  color = l + (color - l) * uLookSat;
  color = outset * color;
  color = pow(max(color, vec3(0.0)), vec3(2.2));
  return clamp(SL_REC2020_TO_SRGB * color, 0.0, 1.0);
}
vec3 slRRTODT(vec3 v) { vec3 a = v * (v + 0.0245786) - 0.000090537; vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081; return a / b; }
vec3 slAces(vec3 c) {
  const mat3 inM = mat3(vec3(0.59719, 0.07600, 0.02840), vec3(0.35458, 0.90834, 0.13383), vec3(0.04823, 0.01566, 0.83777));
  const mat3 outM = mat3(vec3(1.60475, -0.10208, -0.00327), vec3(-0.53108, 1.10813, -0.07276), vec3(-0.07367, -0.00605, 1.07602));
  return clamp(outM * slRRTODT(inM * (c * 1.3)), 0.0, 1.0);
}

float uAspect;

vec3 flare(vec2 uv, vec2 sun, float vis) {
  vec2 asp = vec2(uAspect, 1.0);
  vec2 p = (uv - 0.5) * asp, s = (sun - 0.5) * asp;
  vec2 dv = p - s;
  float r = length(dv);
  vec3 c = vec3(0.0);
  float ang = atan(dv.y, dv.x);
  float spikes = pow(abs(cos(ang * 3.0 + 0.4)), 24.0) + 0.6 * pow(abs(cos(ang * 4.0 - 1.1)), 40.0);
  c += uSunCol * (0.020 / (r * r * 9.0 + 0.010) + 0.10 * exp(-r * 3.2));
  c += uSunCol * spikes * 0.30 * exp(-r * 5.5);
  vec3 g = vec3(0.0);
  float k0 = length(p + s * 0.38); g += vec3(0.30, 0.75, 0.55) * smoothstep(0.085, 0.06, k0) * 0.050;
  float k1 = length(p + s * 0.82); g += vec3(0.85, 0.45, 0.25) * smoothstep(0.045, 0.030, k1) * 0.075;
  float k2 = length(p + s * 1.35); g += vec3(0.35, 0.50, 0.95) * smoothstep(0.17, 0.12, k2) * (0.4 + 0.6 * smoothstep(0.05, 0.16, k2)) * 0.040;
  float k3 = length(p - s * 0.45); g += vec3(0.80, 0.70, 0.35) * smoothstep(0.030, 0.018, k3) * 0.060;
  float hr = length(p + s * 0.15);
  g += vec3(0.45, 0.55, 0.85) * exp(-pow((hr - 0.52) * 16.0, 2.0)) * 0.035 * smoothstep(0.1, 0.5, length(s));
  c += g * uSunCol * 2.4;
  return c * vis;
}

void main() {
  uAspect = pot_ScreenSize.x * pot_ScreenSize.w;
  vec2 c = vUv - 0.5;
  float r2 = dot(c * vec2(uAspect, 1.0), c * vec2(uAspect, 1.0)) / (0.25 * (uAspect * uAspect + 1.0));
  vec4 ad = texture(tAdapt, vec2(0.5));
  vec2 off = c * r2 * (uCA + uDamage * 0.006);
  vec3 col = vec3(texture(tScene, vUv + off).r, texture(tScene, vUv).g, texture(tScene, vUv - off).b);
  col = max(col, vec3(0.0));
  if (uVol > 0.0) col += texture(tVol, vUv).rgb * uVol;

  // 雷电：天空按闪电方向照亮云层，地面按雾量整体提亮（原版体积光环境项 ×(1 + thunder × 1.5)）
  if (uThunder > 0.0) {
    float raw = texture(tDepth, vUv).r;
    vec3 dir = pot_ViewDir(vUv);
    if (pot_IsSky(raw)) {
      float fl = uThunder * pow(max(dot(dir, uFlashDir), 0.0), 5.0);
      col += vec3(0.55, 0.68, 1.0) * fl * (0.4 + 1.6 * smoothstep(0.0, 0.5, dir.y)) * 1.6;
      col += pot_Fog.rgb * uThunder * 0.5;
    } else {
      vec3 wp = pot_WorldPos(vUv, raw);
      col += pot_Fog.rgb * uThunder * 0.9 * (1.0 - pot_FogFactor(wp));
    }
  }

  vec3 soft = texture(tBlur, vUv).rgb;
  col = mix(col, soft, uAds * 0.75 * smoothstep(0.22, 0.85, r2));
  vec3 bloom = texture(tBloom, vUv).rgb;
  vec3 dirt = texture(tDirt, vUv).rgb;
  col = mix(col, bloom, uBloom);
  col += bloom * dirt * uDirt;
  col += texture(tStreak, vUv).rgb * vec3(0.45, 0.62, 1.0) * uStreak;
  vec3 sun = sunScreen();
  float vis = ad.g * sun.z;
  if (vis > 0.002) col += flare(vUv, sun.xy, vis) * uFlare * (1.0 + dirt * 1.5);
  col *= slExposure();
  col += vec3(1.0, 0.97, 0.9) * uFlash * 2.5;
  col = mix(slAces(col), slAgx(col), uAgxMix);

  float l = luma(col);
  vec3 sh = vec3(0.80, 1.01, 1.13), hi = vec3(1.07, 1.0, 0.90);
  col *= mix(sh, hi, smoothstep(0.03, 0.55, l));
  col = mix(col, col * col * (3.0 - 2.0 * col), 0.22);
  col = col * 0.988 + vec3(0.006, 0.0085, 0.011);
  float sat = uSaturation * (1.0 - 0.65 * uLowHealth) * (1.0 - 0.5 * uDamage);
  l = luma(col);
  col = mix(vec3(l), col, sat);
  float vig = uVignette + uLowHealth * 0.55 + uAds * 0.22;
  float vr = smoothstep(0.15 - uAds * 0.08, 1.05, r2);
  col *= 1.0 - vig * vr * vr * (3.0 - 2.0 * vr);
  float edge = smoothstep(0.18, 1.0, r2);
  col = mix(col, vec3(0.55, 0.02, 0.01) * (0.35 + l), clamp(uDamage * edge * 0.85 + uLowHealth * edge * edge * 0.25 * (0.75 + 0.25 * sin(pot_Time.x * 5.0)), 0.0, 1.0));
  col *= 1.0 - uFade;
  col = toSRGB(clamp(col, 0.0, 1.0));
  fragColor = vec4(col, dot(col, vec3(0.299, 0.587, 0.114)));
}

